"""Qualify both original full fixtures in weak mode; never estimate comparative performance."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import signal
import subprocess
import time

import analyze_comparison as analysis
import run_comparison as runner


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--runtime', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    runner.require(args.slot_granted, 'The coordinator must grant the exclusive Java slot')
    runner.environment_check()
    runtime, output = args.runtime.resolve(strict=True), args.output.resolve()
    runner.require(not output.exists(), 'Use a fresh qualification directory; failed pilots are never replaced')
    receipt = runner.read(runtime / 'compile-receipt.json')
    runner.require(receipt['compiled'] and receipt['ownershipIntegrationSourcesIdentical'], 'Unqualified compilation')
    source_hashes = runner.read(runtime / 'sources.json')
    runner.require(all(runner.sha(path) == digest for path, digest in source_hashes.items()), 'Compiled sources changed')
    cp_file = runtime / 'classpath.txt'
    classpath = cp_file.read_text().strip()
    paths = [*classpath.split(os.pathsep), *source_hashes, cp_file, runtime / 'compile-receipt.json',
             runtime / 'sources.json', Path(__file__).resolve(), runner.HERE / 'run_comparison.py',
             runner.HERE / 'analyze_comparison.py', runner.JAVA, runner.JAVA.parent.parent / 'release',
             runner.JAVA.parent.parent / 'lib/modules', runner.JAVA.parent.parent / 'lib/server/libjvm.so']
    inputs = [runner.fingerprint(path) for path in dict.fromkeys(map(str, paths))]
    source = 'retention-qualification-sha256-' + hashlib.sha256(json.dumps(inputs, sort_keys=True).encode()).hexdigest()
    protocol = {'format': 1, 'cohort': str(output), 'cwd': str(runner.ROOT), 'sourceIdentity': source,
                'fixtures': runner.FIXTURES, 'configuration': runner.CONFIG, 'javaVersion': '25.0.5+8-LTS',
                'statisticsScope': 'native-direct-memo-retention-v1', 'statisticsFormat': 2,
                'metadataReservation': {'arrayBase': 80, 'arrayPerSlot': 36,
                                        'weakMetadataPerSlot': 112, 'weakMetadataOverlap': 160},
                'inputs': inputs, 'schedule': [], 'purpose': 'Weak full-fixture lifecycle qualification only',
                'pooling': 'Exclude all pilot timings from the main cohort; no decisions or tuning from pilot latency.'}
    properties = {runner.TRANSPORT: 'off', runner.ENABLED: 'true', runner.RETENTION: 'weak'}
    for ordinal, fixture in enumerate(runner.FIXTURES):
        folder = output / fixture
        command = [str(runner.JAVA), *runner.JVM,
                   '-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags',
                   *['-D' + key + '=' + value for key, value in properties.items()],
                   '-cp', classpath, runner.LAUNCHER, fixture, '--arm=weak', '--source=' + source,
                   '--warmup=8', '--iterations=5', *runner.FIXTURES[fixture]['arguments'],
                   '--consumption=full', '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store')]
        protocol['schedule'].append({'ordinal': ordinal, 'round': 0, 'fixturePosition': ordinal,
                                     'position': 0, 'fixture': fixture, 'arm': 'weak', 'directory': str(folder),
                                     'properties': properties, 'command': command})
    output.mkdir(parents=True)
    (output / 'claims').mkdir()
    runner.write(output / 'protocol.json', protocol)
    protocol_sha = runner.sha(output / 'protocol.json')
    (output / 'protocol.sha256').write_text(protocol_sha + '\n')
    completed = []
    for slot in protocol['schedule']:
        folder = Path(slot['directory'])
        for item in inputs:
            runner.require(runner.fingerprint(item['path']) == item, 'Qualification input changed: ' + item['path'])
        runner.write(output / 'claims' / f"{slot['ordinal']:02d}.json",
                     {'ordinal': slot['ordinal'], 'protocolSha256': protocol_sha, 'claimedEpochNs': time.time_ns(),
                      'command': slot['command'], 'cwd': str(runner.ROOT)})
        folder.mkdir()
        process, failure, started = None, None, time.time_ns()
        print('Qualifying full weak fixture: ' + slot['fixture'], flush=True)
        try:
            with (folder / 'console.log').open('xb') as console:
                process = subprocess.Popen(slot['command'], cwd=runner.ROOT, stdout=console,
                                           stderr=subprocess.STDOUT, start_new_session=True)
                runner.write(folder / 'launch.json', {'ordinal': slot['ordinal'], 'argv': slot['command'],
                             'cwd': str(runner.ROOT), 'pid': process.pid, 'startedEpochNs': started})
                deadline = time.monotonic() + 300
                while process.poll() is None:
                    remaining = deadline - time.monotonic()
                    runner.require(remaining > 0, 'Qualification JVM exceeded its 300-second deadline')
                    try:
                        process.wait(timeout=min(30, remaining))
                    except subprocess.TimeoutExpired:
                        print('Qualification JVM remains active; raw output preserved.', flush=True)
                runner.require(process.returncode == 0, 'Qualification JVM failed: ' + str(process.returncode))
        except BaseException as problem:
            failure = {'exception': type(problem).__name__, 'message': str(problem)}
        finally:
            if process is not None and process.poll() is None:
                os.killpg(process.pid, signal.SIGTERM)
                try:
                    process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    os.killpg(process.pid, signal.SIGKILL)
                    process.wait(timeout=5)
            runner.write(folder / 'process.json', {'startedEpochNs': started, 'finishedEpochNs': time.time_ns(),
                         'exitCode': process.returncode if process else None, 'failure': failure})
        try:
            runner.require(failure is None, 'Qualification process failed: ' + str(failure))
            for item in inputs:
                runner.require(runner.fingerprint(item['path']) == item, 'Qualification input changed: ' + item['path'])
            run = analysis.inspect_slot(protocol, slot, require_completion=False)
            analysis.match_runs(completed + [run])
            runner.write(folder / 'validation.json', {'qualified': True, 'scope': 'full weak fixture lifecycle',
                         'queries': 13, 'memoOwners': 13, 'comparativeTimingEstimate': False})
            runner.write(folder / 'completion.json', {'ordinal': slot['ordinal'], 'protocolSha256': protocol_sha,
                         'completedEpochNs': time.time_ns(),
                         'claimSha256': runner.sha(output / 'claims' / f"{slot['ordinal']:02d}.json"),
                         'rawHashes': {name: runner.sha(folder / name) for name in analysis.RAW_FILES}})
            analysis.inspect_slot(protocol, slot, require_completion=True)
            completed.append(run)
        except BaseException as problem:
            runner.write(output / 'failure.json', {'fixture': slot['fixture'], 'failure': str(problem)})
            raise
    runner.write(output / 'qualification.json', {'qualifiedForTiming': True, 'scope': protocol['purpose'],
                 'requiresSeparateUnitQualification': True, 'jvms': 2, 'queries': 26, 'memoOwners': 26,
                 'runtime': str(runtime), 'sourceIdentity': source, 'sourceHashes': source_hashes,
                 'protocolSha256': protocol_sha, 'runtimeAndSourceInputs': inputs,
                 'completionHashes': {slot['fixture']: runner.sha(Path(slot['directory']) / 'completion.json')
                                      for slot in protocol['schedule']},
                 'comparativeTimingEstimate': False, 'pooling': protocol['pooling']})
    print(json.dumps({'qualifiedWeakFullFixtures': 2, 'queries': 26, 'memoOwners': 26,
                      'receipt': str(output / 'qualification.json'), 'comparativeTimingEstimate': False}))


if __name__ == '__main__':
    main()
